export function getServiceDetails(slug) {
  if (!slug) return null;
  const cleanSlug = slug.toLowerCase().trim();
  if (SERVICES_DETAILS_DATA[cleanSlug]) return SERVICES_DETAILS_DATA[cleanSlug];
  const canonical = SERVICE_SLUG_ALIASES[cleanSlug];
  if (canonical && SERVICES_DETAILS_DATA[canonical]) return SERVICES_DETAILS_DATA[canonical];
  return null;
}
